  var stranded=City(85,10);stranded.buildings.Add(new Building{asset=new BuildingAsset{type="type_mine"}});GodWorldRuntime.State(stranded).era=4;stranded.resources["wood"]=100;stranded.resources["stone"]=100;stranded.resources["common_metals"]=100;NativeLifecycle.Civilization(stranded);Check(GodWorldRuntime.State(stranded).steel==0&&stranded.getResourcesAmount("wood")==100,"unfunded industry cannot consume inputs or make goods");
  var importer=City(86,10);GodWorldRuntime.Issue(importer,false,1000);isState.steel=100;double exportsBefore=isState.business.gold;int imported=NativeLifecycle.IndustrialTrade(industry,importer,null);Check(imported>0&&GodWorldRuntime.State(importer).steel>0&&isState.steel<100,"industrial stocks can move between actual cities");Check(Math.Abs(1000-GodWorldRuntime.GetGold(importer)-(isState.business.gold-exportsBefore))<1e-8,"industrial trade payment conserves buyer and seller money");
  var gunner=new Actor{city=industry,weaponAsset=new EquipmentAsset{id="godworld_industrial_gun"}};isState.ammunition=1;Check(NativeLifecycle.AmmoReady(gunner),"funded firearm has ammunition");NativeLifecycle.Shot(gunner,false);Check(isState.ammunition==1,"failed attack does not consume ammunition");NativeLifecycle.Shot(gunner,true);Check(isState.ammunition==0&&!NativeLifecycle.AmmoReady(gunner),"successful shot consumes ammunition and empty gun cannot fire");gunner.weaponAsset.id="godworld_electric_gun";isState.power=2;NativeLifecycle.Shot(gunner,true);Check(isState.power==1,"energy weapon consumes generated power");var advanced=new EquipmentAsset{id="godworld_industrial_gun"};Check(!NativeLifecycle.ModernEquipment(stranded,advanced),"industrial weapon requires real factory and parts");isState.era=5;isState.factory=1;isState.steel=5;isState.machinery=2;Check(NativeLifecycle.ModernEquipment(industry,advanced),"funded industrial chain unlocks advanced equipment");NativeLifecycle.EquipmentMade(new Item{asset=advanced},industry);Check(isState.steel==3&&isState.machinery==1,"actual equipment creation consumes industrial parts once");
  var saturated=City(87,1);var wealthyWorker=new Actor{city=saturated};wealthyWorker.data.loot=int.MaxValue;GodWorldRuntime.EarnNativeIncome(wealthyWorker,10);Check(GodWorldRuntime.State(saturated).wageArrears==0,"wallet representation capacity does not fabricate an economic debt");
  var godShopper=new Actor{city=publicFunds};NativeLifecycle.IssuePersonal(godShopper,true,10);Check(!NativeLifecycle.CanAfford(godShopper,1)&&NativeLifecycle.LiquidPayment(godShopper,1)==0&&NativeLifecycle.PersonalGod(godShopper)==10,"personal god cannot auto-pay consumption");var unlockedWood=new EquipmentAsset{material="wood"};Check(NativeProgression.AllowEquipment(godShopper,unlockedWood,publicFunds),"native equipment has no added civilization lock");
  World.world.map_stats=new MapStats();Check(GodWorldRuntime.GetRate()==1,"new world has independent rate");checks+=OrganizationTests.Run();Check(UnityEngine.Debug.warnings.Count==0,"no runtime adapter warnings");Console.WriteLine(checks+" native-adapter checks passed");
 }
}


